import logging
import os
import subprocess
from functools import wraps

class AgentIntrospector:
    def __init__(self, rule_lib):
        self.rule_lib = rule_lib
        self.logger = logging.getLogger('agent_introspector')
        logging.basicConfig(level=logging.INFO)

    def capture_error(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                self.logger.error(f'Captured exception: {e}')
                root_cause = self.analyze_root_cause(e)
                if root_cause:
                    self.auto_repair(root_cause)
                else:
                    self.notify_human(e)
                raise
        return wrapper

    def analyze_root_cause(self, exc):
        for rule in self.rule_lib:
            if rule['pattern'] in str(exc):
                return rule
        return None

    def auto_repair(self, rule):
        if rule['action'] == 'create_file':
            path = rule['path']
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, 'w') as f:
                f.write('')
            self.logger.info(f'File created: {path}')
        elif rule['action'] == 'fix_permission':
            os.chmod(rule['path'], 0o755)
            self.logger.info(f'Permission fixed: {rule["path"]}')
        elif rule['action'] == 'install_dep':
            subprocess.run(['pip', 'install', rule['package']], check=True)
            self.logger.info(f'Dependency installed: {rule["package"]}')
        # Additional rate‑limit handling omitted for brevity

    def notify_human(self, exc):
        report = {
            'exception': str(exc),
            'type': type(exc).__name__,
            'timestamp': logging.Formatter.formatTime(logging.Formatter(), self.logger)
        }
        self.logger.warning(f'HUMAN_NOTIFY: {report}')

